import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { saveContact } from "@/lib/actions";
import { readShortlist } from "@/lib/shortlist";

function form(email: string, id?: string) {
  const data = new FormData();
  data.set("email", email);
  data.set("name", "Updated person");
  data.set("jobRole", "Software Engineer Intern");
  if (id) data.set("id", id);
  return data;
}

describe.runIf(databaseTestsEnabled).each([false, true])(
  "repeat contact saves (paid=%s)",
  (paid) => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    beforeAll(async () => {
      fixture = await usageFixture();
      await setGating(boundary.db, true);
    });
    afterAll(async () => {
      if (fixture) await fixture.close();
    });

    async function owner() {
      const f = await usageOwner(boundary.db, { paid });
      boundary.user.mockResolvedValue({ id: f.user.id });
      return f;
    }
    async function receipt(userId: string, email: string) {
      await boundary.db.deliveryReceipt.create({
        data: {
          userId,
          recipientEmail: email,
          createdAt: new Date(),
          sentAt: new Date(),
        },
      });
    }

    it.each(["SENT", "REPLIED"] as const)(
      "restores re-additions after %s without duplicating the archived contact",
      async (status) => {
        const f = await owner();
        const contact = await boundary.db.contact.create({
          data: {
            userId: f.user.id,
            name: "Original",
            email: "[REDACTED_EMAIL]",
            archivedAt: new Date(),
            shortlistRemovedAt: new Date(),
          },
        });
        await boundary.db.campaign.create({
          data: {
            userId: f.user.id,
            templateId: f.template.id,
            status: "COMPLETED",
            sends: {
              create: {
                contactId: contact.id,
                recipientEmail: contact.email,
                status,
                deliveryState: "DONE",
                sentAt: new Date(),
              },
            },
          },
        });
        expect(await saveContact(form("  [REDACTED_EMAIL]  "))).toMatchObject({
          ok: true,
        });
        expect(await saveContact(form(contact.email))).toMatchObject({
          ok: true,
        });
        expect(
          await boundary.db.contact.findFirst({
            where: { id: contact.id, userId: f.user.id },
          }),
        ).toMatchObject({
          name: "Updated person",
          archivedAt: null,
          shortlistRemovedAt: null,
          followUpRequestedAt: expect.any(Date),
        });
        expect(
          await boundary.db.contact.count({
            where: { userId: f.user.id, email: contact.email },
          }),
        ).toBe(1);
        expect((await readShortlist(f.user.id)).contacts).toHaveLength(1);
        expect(
          await boundary.db.send.count({
            where: { campaign: { userId: f.user.id } },
          }),
        ).toBe(1);
      },
    );

    it("allows receipt-only addresses, including changes to an existing contact email", async () => {
      const f = await owner();
      await receipt(f.user.id, "[REDACTED_EMAIL]");
      const contact = await boundary.db.contact.create({
        data: {
          userId: f.user.id,
          name: "Original",
          email: "[REDACTED_EMAIL]",
        },
      });
      expect(
        await saveContact(form("[REDACTED_EMAIL]", contact.id)),
      ).toMatchObject({ ok: true });
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: true,
      });
      expect(
        await boundary.db.contact.count({ where: { userId: f.user.id } }),
      ).toBe(1);
      expect((await readShortlist(f.user.id)).contacts[0]).toMatchObject({
        id: contact.id,
        previouslySent: true,
        followUp: true,
      });
      expect(
        await boundary.db.send.count({
          where: { campaign: { userId: f.user.id } },
        }),
      ).toBe(0);
    });

    it("allows unchanged-email edits and restores shortlist eligibility", async () => {
      const f = await owner();
      const contact = await boundary.db.contact.create({
        data: {
          userId: f.user.id,
          name: "Original",
          email: "[REDACTED_EMAIL]",
          shortlistRemovedAt: new Date(),
        },
      });
      await receipt(f.user.id, contact.email);
      expect(await saveContact(form(contact.email, contact.id))).toMatchObject({
        ok: true,
      });
      expect(
        await boundary.db.contact.findFirst({
          where: { id: contact.id, userId: f.user.id },
        }),
      ).toMatchObject({
        name: "Updated person",
        shortlistRemovedAt: null,
        followUpRequestedAt: expect.any(Date),
      });
      expect((await readShortlist(f.user.id)).contacts).toHaveLength(1);
    });

    it("allows new addresses and ignores another user's delivery history", async () => {
      const other = await usageOwner(boundary.db);
      await receipt(other.user.id, "[REDACTED_EMAIL]");
      const f = await owner();
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: true,
      });
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: true,
      });
      expect(
        await boundary.db.contact.count({ where: { userId: f.user.id } }),
      ).toBe(2);
    });

    it("allows an address with only a failed send", async () => {
      const f = await owner();
      const contact = await boundary.db.contact.create({
        data: {
          userId: f.user.id,
          name: "Original",
          email: "[REDACTED_EMAIL]",
        },
      });
      await boundary.db.campaign.create({
        data: {
          userId: f.user.id,
          templateId: f.template.id,
          status: "COMPLETED",
          sends: {
            create: {
              contactId: contact.id,
              recipientEmail: contact.email,
              status: "FAILED",
              deliveryState: "DONE",
            },
          },
        },
      });
      expect(await saveContact(form(contact.email))).toMatchObject({
        ok: true,
      });
    });

    it("restores repeat additions to the shortlist", async () => {
      const f = await owner();
      await receipt(f.user.id, "[REDACTED_EMAIL]");
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: true,
      });
      expect((await readShortlist(f.user.id)).contacts[0]).toMatchObject({
        email: "[REDACTED_EMAIL]",
        previouslySent: true,
        followUp: true,
      });
    });

    it("preserves legacy access when paid gating is disabled", async () => {
      const f = await owner();
      await receipt(f.user.id, "[REDACTED_EMAIL]");
      await setGating(boundary.db, false);
      try {
        expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
          ok: true,
        });
      } finally {
        await setGating(boundary.db, true);
      }
    });

    it("preserves suspended-account denials instead of requesting an upgrade", async () => {
      const f = await owner();
      await receipt(f.user.id, "[REDACTED_EMAIL]");
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          isSuspended: true,
          suspendedAt: new Date(),
          suspensionReason: "Test suspension",
        },
      });
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: false,
        code: "ACCOUNT_SUSPENDED",
      });
    });
  },
);
